"use client";

import React, { useState, useEffect } from "react";

const matrixTimeline = [
  { day: 1, regime: "ACTIVE_TROUGHS", raw: 82, corr: 96, obs: 94, bust: 18 },
  { day: 2, regime: "ACTIVE_TROUGHS", raw: 110, corr: 134, obs: 129, bust: 25 },
  { day: 3, regime: "BAY_DEPRESSION", raw: 175, corr: 130, obs: 124, bust: 54 },
  { day: 4, regime: "DEEP_DEPRESSION", raw: 210, corr: 145, obs: 138, bust: 76 },
  { day: 5, regime: "CYCLONIC_SURGE", raw: 160, corr: 115, obs: 112, bust: 68 },
  { day: 6, regime: "WD_INTERACTION", raw: 95, corr: 80, obs: null, bust: 49 },
  { day: 7, regime: "BREAK_ONSET", raw: 45, corr: 38, obs: null, bust: 42 },
  { day: 8, regime: "MONSOON_BREAK", raw: 25, corr: 22, obs: null, bust: 35 },
  { day: 9, regime: "FOOTHILL_LOCK", raw: 60, corr: 88, obs: null, bust: 64 },
  { day: 10, regime: "EASTERLY_WAVE", raw: 70, corr: 62, obs: null, bust: 72 },
];

const sectorGrid = [
  {
    id: "GANGA-10",
    name: "GANGETIC PLAIN SECTOR",
    raw: 62,
    corr: 54,
    bust: 34,
    ex64: 42,
    ex115: 14,
    ex204: 3,
    log: "Meridional trough axis oscillation within standard ensemble bounds.",
  },
  {
    id: "ODISHA-07",
    name: "COASTAL ODISHA & NORTH BAY",
    raw: 194,
    corr: 138,
    bust: 76,
    ex64: 91,
    ex115: 72,
    ex204: 28,
    log: "CRITICAL: GFS convective core over-prediction (+56mm bias vs IMD truth).",
  },
  {
    id: "KONKAN-23",
    name: "KONKAN & GOA GHATS",
    raw: 88,
    corr: 146,
    bust: 68,
    ex64: 86,
    ex115: 64,
    ex204: 19,
    log: "Raw 0.25 deg GFS severely under-resolves orographic lift (-58mm deficit).",
  },
  {
    id: "DECCAN-31",
    name: "DECCAN INTERIOR PLATEAU",
    raw: 14,
    corr: 12,
    bust: 14,
    ex64: 6,
    ex115: 1,
    ex204: 0,
    log: "Stable leeward subsidence flow. Minimal historical forecast variance.",
  },
];

export default function KernelTerminalUI() {
  const [day, setDay] = useState<number>(4);
  const [sector, setSector] = useState(sectorGrid[1]); // Default Odisha high risk
  const [logs, setLogs] = useState<string[]>([
    "INITIALIZING FORECASTGUARD KERNEL v2.0.4...",
    "LOADING IMD 0.25 DEG GRIDDED OBSERVATIONS...",
    "PARSING GFS MEDIUM-RANGE ENSEMBLES...",
    "READY FOR OPERATIONAL QUERY.",
  ]);

  const activeDayData = matrixTimeline[day - 1];

  function handleSectorSelect(s: typeof sectorGrid[0]) {
    setSector(s);
    setLogs((prev) => [
      `> SELECT SECTOR: ${s.id} (${s.name})`,
      `> COMPUTING BUST PROBABILITY... [${s.bust}% RISK DETECTED]`,
      ...prev.slice(0, 5),
    ]);
  }

  // ASCII bar generator function for text-based charts
  function renderAsciiBar(val: number, max: number = 220) {
    const totalChars = 24;
    const filled = Math.round((val / max) * totalChars);
    return "█".repeat(Math.max(0, filled)) + "░".repeat(Math.max(0, totalChars - filled));
  }

  return (
    <div className="min-h-screen bg-[#050505] text-[#00ff66] font-mono p-4 md:p-8 selection:bg-[#00ff66] selection:text-black">
      {/* RETRO LINUX KERNEL BANNER */}
      <div className="border border-[#00ff66]/40 p-4 mb-6 bg-black shadow-[0_0_15px_rgba(0,255,102,0.15)]">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-2 border-b border-[#00ff66]/30 pb-3 mb-3">
          <div>
            <h1 className="text-sm md:text-base font-bold tracking-widest text-[#00ff66]">
              LINUX_CLI // FORECASTGUARD KERNEL [SIH26079]
            </h1>
            <p className="text-[11px] text-[#00ff66]/60">
              HOST: ncmrwf-node-04 // PROTOCOL: IMD_MOSDAC_STREAM
            </p>
          </div>
          <div className="text-xs bg-[#00ff66]/10 border border-[#00ff66]/30 px-3 py-1 text-[#00ff66] animate-pulse">
            SYSTEM STATUS: LIVE_INTERCEPT
          </div>
        </div>

        {/* 10-DAY ASCII HORIZON SELECTOR */}
        <div className="text-xs text-[#00ff66]/80 mb-2">
          &gt; SELECT_HORIZON_DAY [1-10]:
        </div>
        <div className="grid grid-cols-5 md:grid-cols-10 gap-2">
          {matrixTimeline.map((item) => {
            const active = item.day === day;
            return (
              <button
                key={item.day}
                onClick={() => setDay(item.day)}
                className={`p-2 text-center border text-xs transition-all ${
                  active
                    ? "bg-[#00ff66] text-black font-bold border-[#00ff66] shadow-[0_0_10px_#00ff66]"
                    : "bg-black text-[#00ff66]/70 border-[#00ff66]/30 hover:border-[#00ff66]"
                }`}
              >
                <div>D{item.day}</div>
                <div className="text-[9px]">{item.bust}%B</div>
              </button>
            );
          })}
        </div>
      </div>

      {/* TERMINAL MAIN GRID */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 mb-6">
        {/* LEFT: SECTOR SELECTOR & ASCII WAVEFORM */}
        <section className="lg:col-span-6 border border-[#00ff66]/40 p-4 bg-black flex flex-col justify-between">
          <div>
            <div className="text-xs border-b border-[#00ff66]/30 pb-2 mb-4 text-[#00ff66] font-bold">
              // SELECT_TARGET_SUBDIVISION_SECTOR
            </div>
            <div className="space-y-2 mb-6">
              {sectorGrid.map((s) => {
                const selected = s.id === sector.id;
                return (
                  <button
                    key={s.id}
                    onClick={() => handleSectorSelect(s)}
                    className={`w-full text-left p-2.5 border text-xs transition-all flex justify-between items-center ${
                      selected
                        ? "bg-[#00ff66]/20 border-[#00ff66] text-white font-bold"
                        : "border-[#00ff66]/20 text-[#00ff66]/70 hover:border-[#00ff66]/60"
                    }`}
                  >
                    <span>[{s.id}] {s.name}</span>
                    <span className={s.bust > 60 ? "text-[#ff0055] font-bold" : "text-[#00ff66]"}>
                      {s.bust}% BUST
                    </span>
                  </button>
                );
              })}
            </div>

            {/* TEXT-BASED ASCII CHART (NO CHARTS.JS OR RECHARTS FLUFF) */}
            <div className="text-xs border-t border-[#00ff66]/30 pt-4">
              <div className="text-[#00ff66]/80 mb-2 font-bold">
                &gt; ASCII_WAVEFORM_COMPARISON [DAY {day}: {activeDayData.regime}]
              </div>
              <div className="space-y-1.5 text-[11px] font-mono">
                <div>
                  <span className="text-sky-400">RAW_GFS :</span> {renderAsciiBar(activeDayData.raw)} {activeDayData.raw}mm
                </div>
                <div>
                  <span className="text-amber-400">CORRECTED:</span> {renderAsciiBar(activeDayData.corr)} {activeDayData.corr}mm
                </div>
                <div>
                  <span className="text-white">IMD_OBS :</span> {renderAsciiBar(activeDayData.obs ?? 0)} {activeDayData.obs ?? "N/A"}mm
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* RIGHT: TARGET DETAILS & TERMINAL LOGS */}
        <section className="lg:col-span-6 border border-[#00ff66]/40 p-4 bg-black flex flex-col justify-between">
          <div>
            <div className="text-xs border-b border-[#00ff66]/30 pb-2 mb-4 text-[#00ff66] font-bold">
              // TARGET_TELEMETRY: {sector.id}
            </div>

            <div className="text-xs space-y-3 mb-6">
              <div className="bg-[#00ff66]/5 border border-[#00ff66]/20 p-3">
                <div className="text-[#00ff66]/60 text-[10px]">DIAGNOSTIC REASONING:</div>
                <div className="text-white mt-1">{sector.log}</div>
              </div>

              <div className="grid grid-cols-3 gap-2 text-center">
                <div className="border border-[#00ff66]/30 p-2">
                  <div className="text-[9px] text-[#00ff66]/60">&gt;64.5MM HEAVY</div>
                  <div className="text-base font-bold text-white mt-1">{sector.ex64}%</div>
                </div>
                <div className="border border-[#00ff66]/30 p-2">
                  <div className="text-[9px] text-[#00ff66]/60">&gt;115.5MM V.HEAVY</div>
                  <div className="text-base font-bold text-white mt-1">{sector.ex115}%</div>
                </div>
                <div className="border border-[#00ff66]/30 p-2">
                  <div className="text-[9px] text-[#00ff66]/60">&gt;204.5MM EXTREME</div>
                  <div className="text-base font-bold text-white mt-1">{sector.ex204}%</div>
                </div>
              </div>
            </div>
          </div>

          {/* REAL-TIME TERMINAL LOG WINDOW */}
          <div className="border border-[#00ff66]/30 bg-[#020d05] p-3 text-[11px] h-[140px] overflow-y-auto font-mono">
            <div className="text-[#00ff66]/50 mb-1">=== SYSTEM KERNEL LOGS ===</div>
            {logs.map((log, idx) => (
              <div key={idx} className="text-[#00ff66]/90">
                {log}
              </div>
            ))}
          </div>
        </section>
      </div>

      {/* FOOTER PROMPT */}
      <footer className="border border-[#00ff66]/40 p-3 bg-black text-xs flex items-center gap-2">
        <span className="text-[#00ff66] animate-pulse">root@ncmrwf:~#</span>
        <span className="text-white">forecastguard --run-prediction --day={day} --target={sector.id}</span>
      </footer>
    </div>
  );
}